import XCTest
@testable import ChecklistIPC
@testable import ChecklistCore

final class HandoffInstructionTests: XCTestCase {
    let liveCLI = "/Applications/Checklist.app/Contents/MacOS/checklist"
    // Literal base text plus the integrated CL-167 ticket reference, not generated by the helpers.
    let formerOrdinary = #"Use Checklist for CL-42: Synthetic handoff. Work in /synthetic/workspace. Run /Applications/Checklist.app/Contents/MacOS/checklist connect --task ticket from that workspace; it registers this actual thread and attaches it to the ticket. Then run /Applications/Checklist.app/Contents/MacOS/checklist call task_context '{"project_id":"project","task_id":"ticket"}' to read the task, project rules and notes. Run checklist tools for the supported schemas. Connecting alone does not claim or assign work."#
    let formerReview = #"Start a fresh independent Codex reviewer conversation for ticket metadata project "Synthetic project": CL-42 "Synthetic handoff". Do not reuse an implementation contributor or its delegated/prior identity. Work in /synthetic/workspace. Run /Applications/Checklist.app/Contents/MacOS/checklist connect --task ticket from that workspace. Discover checklist tools, then call review_context with this exact JSON: {"gate":"review"}. Read the complete brief, acceptance, findings, immutable target and current review_contract; fetch captured AGENTS.md and its linked project rules. Claim this exact request with phase review, current task revision, gate and manifest before review. Refresh review_context after claiming to obtain the applied requirement revision and contract SHA; pre-claim preparation is a preview. Assess every acceptance and project requirement critically; choose meaningful checks in your own session, attach your own hashed report/log/screenshots with attachment_add, and record review_assessment against the fresh contract SHA-256. No swift_test or validate-plan receipt is required. On rework, follow the case-level failed-only guidance in review_context: carry input-valid passes with original provenance, run only failed/inconclusive/materially affected checks, explain broader selection by named changed inputs or an applicable explicit effective project workflow/context instruction, and report carried versus newly executed evidence. A fixture-only repair needs no all-green rerun; no prior verdict or approval transfers and all fresh gates remain required. Report pass, changes or blocked honestly, preserving stable finding IDs. Preparing this prompt starts no turn and acquires no claim."#
    func prompts(_ instance: ChecklistInstance) throws -> [String] {
        let directory = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try FileManager.default.createDirectory(at:directory,withIntermediateDirectories:true)
        defer { try? FileManager.default.removeItem(at:directory) }
        let router = try CommandRouter(root:directory,cliCommand:instance.cliCommand)
        let ordinary = try ChecklistHandoff.instruction(key:"CL-42",title:"Synthetic handoff",root:"/synthetic/workspace",projectID:"project",taskID:"ticket",cliCommand:instance.cliCommand)
        let review = router.agentReviewInstruction(provider:"codex",task:["key":"CL-42","id":"ticket","title":"Synthetic handoff"],root:"/synthetic/workspace",json:#"{"gate":"review"}"#,reference:AgentReference.text(key:"CL-42",title:"Synthetic handoff",projectName:"Synthetic project"))
        return [ordinary,review]
    }
    func testLiveAndStagedNoSlotPromptsAreByteEqualToFormerText() throws {
        for bundle in [nil,URL(fileURLWithPath:"/temporary stage/Checklist.app")] as [URL?] {
            let instance = try ChecklistInstance(bundleURL:bundle,environment:["CHECKLIST_DATA_ROOT":"/tmp/custom-live"])
            XCTAssertEqual(instance.cliCommand,liveCLI)
            let actual = try prompts(instance)
            XCTAssertEqual(Data(actual[0].utf8),Data(formerOrdinary.utf8))
            XCTAssertEqual(Data(actual[1].utf8),Data(formerReview.utf8))
        }
    }
    func testBothHandoffsUseEverySlotsShellQuotedBundleCLI() throws {
        for slot in 1...4 {
            let bundle = URL(fileURLWithPath:"/Users/Synthetic Owner's Data/Checklist Test \(slot).app")
            let instance = try ChecklistInstance(slotValue:slot,bundleURL:bundle)
            let expected = "'/Users/Synthetic Owner'\\''s Data/Checklist Test \(slot).app/Contents/MacOS/checklist'"
            XCTAssertEqual(instance.cliCommand,expected)
            let actual = try prompts(instance)
            XCTAssertEqual(actual[0],formerOrdinary.replacingOccurrences(of:liveCLI,with:expected))
            XCTAssertEqual(actual[1],formerReview.replacingOccurrences(of:liveCLI,with:expected))
            XCTAssertTrue(actual.allSatisfy {!$0.contains(liveCLI)})
        }
    }
}
